public static void solve(FastScanner sc, FastPrintStream pw) throws Exception {
    int times = sc.nextInt();
    for (int time = 0; time < times; time++) {
        long a[] = new long[5];
        long p[] = new long[5];
        Arrays.setAll(a, i -> sc.nextLong());
        Arrays.setAll(p, i -> sc.nextLong());
        long now = 0;
        long count = 0;
        for (int i = 0; i < 5; i++) {
            now += a[i] * (i + 1);
            count += a[i];
        }
        if (now / count >= 3) {
            pw.println(0);
            continue;
        }
        long sa = 3 * count - now;
        if (2 * p[3] <= p[4]) {
            if (sa % 2 == 1) {
                long b = sa / 2;
                pw.println(Math.min(p[3] + p[4] * b, p[4] * (b + 1)));
            } else {
                pw.println(sa * p[4] / 2);
            }
        } else {
            pw.println(sa * p[3]);
        }
    }
}
